static size_t lonejson__format_size_decimal(char *out, size_t out_size,
                                            size_t value) {
  char reversed[sizeof(size_t) * 3u + 1u];
  size_t len = 0u;
  size_t i;

  do {
    reversed[len] = (char)('0' + (value % 10u));
    value /= 10u;
    ++len;
  } while (value != 0u && len < sizeof(reversed));

  if (out_size <= len) {
    return len;
  }
  for (i = 0u; i < len; ++i) {
    out[i] = reversed[len - 1u - i];
  }
  out[len] = '\0';
  return len;
}

static size_t lonejson__format_u64_decimal(char *out, size_t out_size,
                                           lonejson_uint64 value) {
  char reversed[sizeof(lonejson_uint64) * 3u + 1u];
  size_t len = 0u;
  size_t i;

  do {
    lonejson_uint64 digit = value % 10u;
    reversed[len] = (char)('0' + (int)digit);
    value /= 10u;
    ++len;
  } while (value != 0u && len < sizeof(reversed));

  if (out_size <= len) {
    return len;
  }
  for (i = 0u; i < len; ++i) {
    out[i] = reversed[len - 1u - i];
  }
  out[len] = '\0';
  return len;
}

