static lonejson_status lonejson__writer_array_items_spooled_with_options(
    lonejson_writer *writer, const char *selector,
    const lonejson_spooled *value, const lonejson__parse_options *options,
    lonejson_error *error) {
  lonejson_spooled cursor;

  if (value == NULL) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_ARGUMENT,
                                      "spooled array item source is required");
  }
  cursor = *value;
  if (lonejson_spooled_rewind(&cursor, error) != LONEJSON_STATUS_OK) {
    return error != NULL ? error->code : LONEJSON_STATUS_IO_ERROR;
  }
  return lonejson__writer_array_items_reader_with_options(
      writer, selector, lonejson__writer_spooled_reader, &cursor, options,
      error);
}

lonejson_status lonejson_writer_array_items_spooled(
    lonejson_writer *writer, const char *selector,
    const lonejson_spooled *value, lonejson_error *error) {
  return lonejson__writer_array_items_spooled_with_options(
      writer, selector, value, lonejson__writer_runtime_parse_options(writer),
      error);
}

lonejson_status lonejson_writer_mapped(lonejson_writer *writer,
                                       const lonejson_map *map, const void *src,
                                       lonejson_error *error) {
  lonejson__generator_frame root;

  if (map == NULL || src == NULL) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_ARGUMENT,
                                      "map and source are required");
  }
  memset(&root, 0, sizeof(root));
  root.kind = LONEJSON__GEN_FRAME_MAP;
  root.u.map.map = map;
  root.u.map.src = src;
  return lonejson__writer_child_event(writer, LONEJSON__WRITER_EVENT_CHILD, map,
                                      src, 6u, &root, error);
}

lonejson_status lonejson_writer_finish(lonejson_writer *writer,
                                       lonejson_error *error) {
  lonejson__writer_state *state;
  lonejson_status status;

  if (writer == NULL || writer->state == NULL) {
    return lonejson__writer_set_error(
        writer, error, LONEJSON_STATUS_INVALID_ARGUMENT, "writer is required");
  }
  state = (lonejson__writer_state *)writer->state;
  if (state->failed) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer is in a failed state");
  }
  if (state->value_stream_active) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer value stream is still open");
  }
  if (state->string_open) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer string is still open");
  }
  if (state->number_open) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer number is still open");
  }
  if (!state->root_written) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer emitted no JSON value");
  }
  if (state->frame_count != 0u) {
    return lonejson__writer_set_error(writer, error,
                                      LONEJSON_STATUS_INVALID_JSON,
                                      "writer has unclosed containers");
  }
  if (state->sink_buffer_len != 0u) {
    status = state->sink(state->sink_user, state->sink_buffer,
                         state->sink_buffer_len,
                         error != NULL ? error : &writer->error);
    if (status != LONEJSON_STATUS_OK && status != LONEJSON_STATUS_TRUNCATED) {
      state->failed = 1;
      if (error == NULL && writer->error.code == LONEJSON_STATUS_OK) {
        lonejson__set_error(&writer->error, status, 0u, 0u, 0u,
                            "writer sink failed");
      }
    }
    if (status != LONEJSON_STATUS_OK) {
      return status;
    }
    state->sink_buffer_len = 0u;
  }
  state->finished = 1;
  return LONEJSON_STATUS_OK;
}

lonejson_status
lonejson_write_json_string_sink(lonejson *runtime, lonejson_reader_fn reader,
                                void *reader_user, lonejson_sink_fn sink,
                                void *sink_user, lonejson_error *error) {
  lonejson_writer writer;
  lonejson_status status;

  status = lonejson_writer_init_sink(runtime, &writer, sink, sink_user, error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  status = lonejson_writer_string_reader(&writer, reader, reader_user, error);
  if (status == LONEJSON_STATUS_OK) {
    status = lonejson_writer_finish(&writer, error);
  }
  lonejson_writer_cleanup(&writer);
  return status;
}

lonejson_status
lonejson_write_json_string_buffer_sink(lonejson *runtime, const void *data,
                                       size_t len, lonejson_sink_fn sink,
                                       void *sink_user, lonejson_error *error) {
  lonejson_writer writer;
  lonejson_status status;

  status = lonejson_writer_init_sink(runtime, &writer, sink, sink_user, error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  status = lonejson_writer_string(&writer, data, len, error);
  if (status == LONEJSON_STATUS_OK) {
    status = lonejson_writer_finish(&writer, error);
  }
  lonejson_writer_cleanup(&writer);
  return status;
}

lonejson_status lonejson_write_json_string_spooled_sink(
    lonejson *runtime, const lonejson_spooled *value, lonejson_sink_fn sink,
    void *sink_user, lonejson_error *error) {
  lonejson_writer writer;
  lonejson_status status;

  status = lonejson_writer_init_sink(runtime, &writer, sink, sink_user, error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  status = lonejson_writer_string_spooled(&writer, value, error);
  if (status == LONEJSON_STATUS_OK) {
    status = lonejson_writer_finish(&writer, error);
  }
  lonejson_writer_cleanup(&writer);
  return status;
}
typedef enum lonejson__value_rewrite_frame_kind {
  LONEJSON__VALUE_REWRITE_FRAME_OBJECT = 1,
  LONEJSON__VALUE_REWRITE_FRAME_ARRAY = 2
} lonejson__value_rewrite_frame_kind;

typedef struct lonejson__value_rewrite_frame {
  lonejson__value_rewrite_frame_kind kind;
  size_t path_len;
  size_t count;
  int prefix_matches;
  int saw_target_child;
  char *key;
  size_t key_len;
  size_t key_cap;
} lonejson__value_rewrite_frame;

typedef struct lonejson__value_rewrite_state {
  lonejson_writer writer;
  lonejson_value_rewrite_options options;
  lonejson__parse_options parse_options;
  lonejson_allocator allocator;
  lonejson_error *error;
  lonejson_value_rewrite_old_value old_value;
  lonejson__value_rewrite_frame *frames;
  size_t frame_count;
  size_t frame_cap;
  lonejson__byte_buffer number;
  size_t number_limit;
  int found;
  int current_emit;
  int current_replace;
  int replacing;
  size_t replace_depth;
  int skipping;
  size_t skip_depth;
} lonejson__value_rewrite_state;

typedef struct lonejson__value_rewrite_selector {
  lonejson_allocator allocator;
  char **segments;
  size_t segment_count;
  size_t segment_cap;
} lonejson__value_rewrite_selector;

static int lonejson__value_rewrite_segment_is_index(const char *segment) {
  const unsigned char *p;

  if (segment == NULL || segment[0] == '\0') {
    return 0;
  }
  p = (const unsigned char *)segment;
  while (*p != '\0') {
    if (!isdigit(*p)) {
      return 0;
    }
    p++;
  }
  return 1;
}

static void lonejson__value_rewrite_selector_cleanup(
    lonejson__value_rewrite_selector *selector) {
  size_t i;

  if (selector == NULL) {
    return;
  }
  for (i = 0u; i < selector->segment_count; ++i) {
    if (selector->segments[i] != NULL) {
      lonejson__buffer_free(&selector->allocator, selector->segments[i],
                            strlen(selector->segments[i]) + 1u);
    }
  }
  lonejson__buffer_free(&selector->allocator, selector->segments,
                        selector->segment_cap * sizeof(*selector->segments));
  memset(selector, 0, sizeof(*selector));
}

static lonejson_status
lonejson__value_rewrite_selector_add(lonejson__value_rewrite_selector *selector,
                                     const char *data, size_t len,
                                     lonejson_error *error) {
  char **next_segments;
  char *copy;
  size_t next_cap;

  if (len == 0u) {
    return lonejson__set_error(error, LONEJSON_STATUS_INVALID_ARGUMENT, 0u, 0u,
                               0u,
                               "value rewrite selector contains empty segment");
  }
  if (selector->segment_count == selector->segment_cap) {
    next_cap = selector->segment_cap == 0u ? 4u : selector->segment_cap * 2u;
    next_segments = (char **)lonejson__buffer_realloc(
        &selector->allocator, selector->segments,
        selector->segment_cap * sizeof(*selector->segments),
        next_cap * sizeof(*selector->segments));
    if (next_segments == NULL) {
      return lonejson__set_error(error, LONEJSON_STATUS_ALLOCATION_FAILED, 0u,
                                 0u, 0u,
                                 "failed to allocate value rewrite selector");
    }
    selector->segments = next_segments;
    selector->segment_cap = next_cap;
  }
  copy = (char *)lonejson__buffer_alloc(&selector->allocator, len + 1u);
  if (copy == NULL) {
    return lonejson__set_error(error, LONEJSON_STATUS_ALLOCATION_FAILED, 0u, 0u,
                               0u,
                               "failed to allocate value rewrite selector "
                               "segment");
  }
  memcpy(copy, data, len);
  copy[len] = '\0';
  selector->segments[selector->segment_count++] = copy;
  return LONEJSON_STATUS_OK;
}

static lonejson_status lonejson__value_rewrite_parse_selector(
    lonejson__value_rewrite_selector *selector, const char *text,
    const lonejson_allocator *allocator, lonejson_error *error) {
  lonejson__byte_buffer segment;
  lonejson_status status;
  const char *p;

  memset(selector, 0, sizeof(*selector));
  selector->allocator = lonejson__allocator_resolve(allocator);
  memset(&segment, 0, sizeof(segment));
  if (text == NULL || text[0] == '\0') {
    return LONEJSON_STATUS_OK;
  }
  p = text;
  while (*p != '\0') {
    if (*p == '.') {
      status = lonejson__value_rewrite_selector_add(selector, segment.data,
                                                    segment.len, error);
      if (status != LONEJSON_STATUS_OK) {
        lonejson__byte_free(&segment, &selector->allocator);
        return status;
      }
      lonejson__byte_reset(&segment);
      p++;
      continue;
    }
    if (*p == '\\') {
      p++;
      if (*p == '\0') {
        lonejson__byte_free(&segment, &selector->allocator);
        return lonejson__set_error(
            error, LONEJSON_STATUS_INVALID_ARGUMENT, 0u, 0u, 0u,
            "value rewrite selector ends with an escape");
      }
    }
    status = lonejson__byte_append(&segment, p, 1u, SIZE_MAX - 1u,
                                   &selector->allocator, error);
    if (status != LONEJSON_STATUS_OK) {
      lonejson__byte_free(&segment, &selector->allocator);
      return status;
    }
    p++;
  }
  status = lonejson__value_rewrite_selector_add(selector, segment.data,
                                                segment.len, error);
  lonejson__byte_free(&segment, &selector->allocator);
  return status;
}

static lonejson__value_rewrite_frame *
lonejson__value_rewrite_top(lonejson__value_rewrite_state *state) {
  return state->frame_count == 0u ? NULL
                                  : &state->frames[state->frame_count - 1u];
}

static size_t lonejson__value_rewrite_format_size(char *buffer, size_t capacity,
                                                  size_t value) {
  char tmp[32];
  size_t len;

  len = 0u;
  do {
    tmp[len++] = (char)('0' + (value % 10u));
    value /= 10u;
  } while (value != 0u && len < sizeof(tmp));
  if (len + 1u > capacity) {
    return 0u;
  }
  {
    size_t i;
    for (i = 0u; i < len; ++i) {
      buffer[i] = tmp[len - i - 1u];
    }
  }
  buffer[len] = '\0';
  return len;
}

static int lonejson__value_rewrite_source_is_valid(
    const lonejson_value_rewrite_replacement *source) {
  int forms;

  if (source == NULL) {
    return 0;
  }
  forms = 0;
  if (source->emit != NULL) {
    forms++;
  }
  if (source->json != NULL) {
    forms++;
  }
  if (source->map != NULL || source->src != NULL) {
    forms++;
  }
  if (forms != 1) {
    return 0;
  }
  if (source->emit != NULL) {
    return source->map == NULL && source->src == NULL && source->json == NULL;
  }
  if (source->json != NULL) {
    return source->map == NULL && source->src == NULL &&
           lonejson_json_value_is_rewindable(source->json);
  }
  return source->map != NULL && source->src != NULL;
}

static lonejson_status lonejson__value_rewrite_emit_source(
    lonejson__value_rewrite_state *state,
    const lonejson_value_rewrite_replacement *source) {
  if (!lonejson__value_rewrite_source_is_valid(source)) {
    return lonejson__set_error(state->error, LONEJSON_STATUS_INVALID_ARGUMENT,
                               0u, 0u, 0u,
                               "value rewrite replacement source is invalid");
  }
  if (source->emit != NULL) {
    return source->emit(&state->writer, source->emit_user, state->error);
  }
  if (source->json != NULL) {
    return lonejson_writer_json_value(&state->writer, source->json,
                                      state->error);
  }
  return lonejson_writer_mapped(&state->writer, source->map, source->src,
                                state->error);
}

static lonejson_status
lonejson__value_rewrite_visit_event(lonejson__value_rewrite_state *state,
                                    lonejson_value_event_fn fn) {
  if (fn == NULL) {
    return LONEJSON_STATUS_OK;
  }
  return fn(state->options.old_value_user, state->error);
}

static lonejson_status
lonejson__value_rewrite_visit_chunk(lonejson__value_rewrite_state *state,
                                    lonejson_value_chunk_fn fn,
                                    const char *data, size_t len) {
  if (fn == NULL) {
    return LONEJSON_STATUS_OK;
  }
  return fn(state->options.old_value_user, data, len, state->error);
}

static lonejson_status
lonejson__value_rewrite_visit_bool(lonejson__value_rewrite_state *state,
                                   int value) {
  if (state->options.old_value_visitor == NULL ||
      state->options.old_value_visitor->boolean_value == NULL) {
    return LONEJSON_STATUS_OK;
  }
  return state->options.old_value_visitor->boolean_value(
      state->options.old_value_user, value, state->error);
}

static lonejson_status
lonejson__value_rewrite_replace_with(lonejson__value_rewrite_state *state) {
  if (state->options.replace == NULL) {
    return lonejson__set_error(state->error, LONEJSON_STATUS_INVALID_ARGUMENT,
                               0u, 0u, 0u,
                               "value rewrite replace callback is required");
  }
  return state->options.replace(&state->writer, &state->old_value,
                                state->options.replace_user, state->error);
}

static void
lonejson__value_rewrite_begin_replace_with(lonejson__value_rewrite_state *state,
                                           lonejson_value_type type) {
  memset(&state->old_value, 0, sizeof(state->old_value));
  state->old_value.present = 1;
  state->old_value.type = type;
  state->replacing = 1;
  state->replace_depth = 0u;
}

static int lonejson__value_rewrite_parent_child_matches(
    lonejson__value_rewrite_state *state,
    const lonejson__value_rewrite_frame *parent) {
  char index_text[32];
  size_t len;

  if (parent == NULL || !parent->prefix_matches ||
      parent->path_len >= state->options.target_segment_count) {
    return 0;
  }
  if (parent->kind == LONEJSON__VALUE_REWRITE_FRAME_OBJECT) {
    return parent->key_len ==
               strlen(state->options.target_segments[parent->path_len]) &&
           memcmp(parent->key, state->options.target_segments[parent->path_len],
                  parent->key_len) == 0;
  }
  len = lonejson__value_rewrite_format_size(index_text, sizeof(index_text),
                                            parent->count);
  if (len == 0u) {
    return 0;
  }
  return strcmp(index_text, state->options.target_segments[parent->path_len]) ==
         0;
}

static lonejson_status
lonejson__value_rewrite_push_frame(lonejson__value_rewrite_state *state,
                                   lonejson__value_rewrite_frame_kind kind,
                                   size_t path_len, int prefix_matches) {
  lonejson__value_rewrite_frame *next;
  size_t next_cap;

  if (state->frame_count == state->frame_cap) {
    next_cap = state->frame_cap == 0u ? 8u : state->frame_cap * 2u;
    next = (lonejson__value_rewrite_frame *)lonejson__buffer_realloc(
        &state->allocator, state->frames,
        state->frame_cap * sizeof(*state->frames),
        next_cap * sizeof(*state->frames));
    if (next == NULL) {
      return lonejson__set_error(state->error,
                                 LONEJSON_STATUS_ALLOCATION_FAILED, 0u, 0u, 0u,
                                 "failed to grow value rewrite stack");
    }
    state->frames = next;
    state->frame_cap = next_cap;
  }
  memset(&state->frames[state->frame_count], 0,
         sizeof(state->frames[state->frame_count]));
  state->frames[state->frame_count].kind = kind;
  state->frames[state->frame_count].path_len = path_len;
  state->frames[state->frame_count].prefix_matches = prefix_matches;
  state->frame_count++;
  return LONEJSON_STATUS_OK;
}

static lonejson_status
lonejson__value_rewrite_pop_frame(lonejson__value_rewrite_state *state) {
  lonejson__value_rewrite_frame *frame;

  if (state->frame_count == 0u) {
    return lonejson__set_error(state->error, LONEJSON_STATUS_INTERNAL_ERROR, 0u,
                               0u, 0u, "value rewrite frame underflow");
  }
  frame = &state->frames[state->frame_count - 1u];
  lonejson__buffer_free(&state->allocator, frame->key, frame->key_cap);
  memset(frame, 0, sizeof(*frame));
  state->frame_count--;
  return LONEJSON_STATUS_OK;
}

static lonejson_status lonejson__value_rewrite_emit_missing_chain(
    lonejson__value_rewrite_state *state,
    lonejson__value_rewrite_frame *frame) {
  size_t i;
  size_t open_objects;
  lonejson_status status;

  if (state->found ||
      (state->options.action != LONEJSON_VALUE_REWRITE_REPLACE &&
       state->options.action != LONEJSON_VALUE_REWRITE_REPLACE_WITH) ||
      !frame->prefix_matches ||
      frame->path_len >= state->options.target_segment_count ||
      frame->saw_target_child ||
      lonejson__value_rewrite_segment_is_index(
          state->options.target_segments[frame->path_len])) {
    return LONEJSON_STATUS_OK;
  }
  status = lonejson_writer_key(
      &state->writer, state->options.target_segments[frame->path_len],
      strlen(state->options.target_segments[frame->path_len]), state->error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  if (frame->path_len + 1u == state->options.target_segment_count) {
    if (state->options.action == LONEJSON_VALUE_REWRITE_REPLACE_WITH) {
      memset(&state->old_value, 0, sizeof(state->old_value));
      state->old_value.type = LONEJSON_VALUE_ABSENT;
      status = lonejson__value_rewrite_replace_with(state);
    } else {
      status = lonejson__value_rewrite_emit_source(state,
                                                   &state->options.replacement);
    }
    state->found = status == LONEJSON_STATUS_OK;
    return status;
  }
  open_objects = 0u;
  status = lonejson_writer_begin_object(&state->writer, state->error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  open_objects++;
  for (i = frame->path_len + 1u; i < state->options.target_segment_count; ++i) {
    if (lonejson__value_rewrite_segment_is_index(
            state->options.target_segments[i])) {
      return lonejson__set_error(
          state->error, LONEJSON_STATUS_TYPE_MISMATCH, 0u, 0u, 0u,
          "value rewrite cannot synthesize a missing array index");
    }
    if (i + 1u == state->options.target_segment_count) {
      status = lonejson_writer_key(
          &state->writer, state->options.target_segments[i],
          strlen(state->options.target_segments[i]), state->error);
      if (status != LONEJSON_STATUS_OK) {
        return status;
      }
      if (state->options.action == LONEJSON_VALUE_REWRITE_REPLACE_WITH) {
        memset(&state->old_value, 0, sizeof(state->old_value));
        state->old_value.type = LONEJSON_VALUE_ABSENT;
        status = lonejson__value_rewrite_replace_with(state);
      } else {
        status = lonejson__value_rewrite_emit_source(
            state, &state->options.replacement);
      }
      if (status != LONEJSON_STATUS_OK) {
        return status;
      }
      break;
    }
    status = lonejson_writer_key(
        &state->writer, state->options.target_segments[i],
        strlen(state->options.target_segments[i]), state->error);
    if (status != LONEJSON_STATUS_OK) {
      return status;
    }
    status = lonejson_writer_begin_object(&state->writer, state->error);
    if (status != LONEJSON_STATUS_OK) {
      return status;
    }
    open_objects++;
  }
  while (open_objects != 0u) {
    status = lonejson_writer_end_object(&state->writer, state->error);
    if (status != LONEJSON_STATUS_OK) {
      return status;
    }
    open_objects--;
  }
  state->found = 1;
  return LONEJSON_STATUS_OK;
}

static lonejson_status lonejson__value_rewrite_before_value(
    lonejson__value_rewrite_state *state, int *emit_original,
    int *push_prefix_matches, size_t *value_path_len) {
  lonejson__value_rewrite_frame *parent;
  int child_matches;
  lonejson_status status;

  *emit_original = 0;
  *push_prefix_matches = 0;
  *value_path_len = 0u;
  if (state->skipping) {
    return LONEJSON_STATUS_OK;
  }
  parent = lonejson__value_rewrite_top(state);
  child_matches = lonejson__value_rewrite_parent_child_matches(state, parent);
  if (parent != NULL) {
    *value_path_len = parent->path_len + 1u;
    if (child_matches) {
      parent->saw_target_child = 1;
    }
    *push_prefix_matches = child_matches;
    if (parent->kind == LONEJSON__VALUE_REWRITE_FRAME_ARRAY) {
      parent->count++;
    }
  } else {
    *push_prefix_matches = 1;
  }
  if (*value_path_len == state->options.target_segment_count &&
      (parent == NULL || child_matches)) {
    state->found = 1;
    if (state->options.action == LONEJSON_VALUE_REWRITE_KEEP) {
      *emit_original = 1;
      if (parent != NULL &&
          parent->kind == LONEJSON__VALUE_REWRITE_FRAME_OBJECT) {
        status = lonejson_writer_key(&state->writer, parent->key,
                                     parent->key_len, state->error);
        if (status != LONEJSON_STATUS_OK) {
          return status;
        }
      }
      return LONEJSON_STATUS_OK;
    }
    if (state->options.action == LONEJSON_VALUE_REWRITE_DROP) {
      return LONEJSON_STATUS_OK;
    }
    if (parent != NULL &&
        parent->kind == LONEJSON__VALUE_REWRITE_FRAME_OBJECT) {
      status = lonejson_writer_key(&state->writer, parent->key, parent->key_len,
                                   state->error);
      if (status != LONEJSON_STATUS_OK) {
        return status;
      }
    }
    if (state->options.action == LONEJSON_VALUE_REWRITE_REPLACE) {
      return lonejson__value_rewrite_emit_source(state,
                                                 &state->options.replacement);
    }
    if (state->options.action == LONEJSON_VALUE_REWRITE_REPLACE_WITH) {
      state->current_replace = 1;
      return LONEJSON_STATUS_OK;
    }
  } else {
    *emit_original = 1;
    if (parent != NULL &&
        parent->kind == LONEJSON__VALUE_REWRITE_FRAME_OBJECT) {
      status = lonejson_writer_key(&state->writer, parent->key, parent->key_len,
                                   state->error);
      if (status != LONEJSON_STATUS_OK) {
        return status;
      }
    }
  }
  return LONEJSON_STATUS_OK;
}

static lonejson_status lonejson__value_rewrite_object_begin(void *user,
                                                            lonejson_error *e) {
  lonejson__value_rewrite_state *state = (lonejson__value_rewrite_state *)user;
  int emit_original;
  int prefix_matches;
  size_t path_len;
  lonejson_status status;

  (void)e;
  if (state->replacing) {
    state->replace_depth++;
    return lonejson__value_rewrite_visit_event(
        state, state->options.old_value_visitor
                   ? state->options.old_value_visitor->object_begin
                   : NULL);
  }
  if (state->skipping) {
    state->skip_depth++;
    return LONEJSON_STATUS_OK;
  }
  status = lonejson__value_rewrite_before_value(state, &emit_original,
                                                &prefix_matches, &path_len);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  if (!emit_original) {
    if (state->current_replace) {
      lonejson__value_rewrite_begin_replace_with(state, LONEJSON_VALUE_OBJECT);
      state->replace_depth = 1u;
      state->current_replace = 0;
      return lonejson__value_rewrite_visit_event(
          state, state->options.old_value_visitor
                     ? state->options.old_value_visitor->object_begin
                     : NULL);
    }
    state->skipping = 1;
    state->skip_depth = 1u;
    return LONEJSON_STATUS_OK;
  }
  status = lonejson_writer_begin_object(&state->writer, state->error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  return lonejson__value_rewrite_push_frame(
      state, LONEJSON__VALUE_REWRITE_FRAME_OBJECT, path_len, prefix_matches);
}

static lonejson_status lonejson__value_rewrite_object_end(void *user,
                                                          lonejson_error *e) {
  lonejson__value_rewrite_state *state = (lonejson__value_rewrite_state *)user;
  lonejson__value_rewrite_frame *frame;
  lonejson_status status;

  (void)e;
  if (state->replacing) {
    status = lonejson__value_rewrite_visit_event(
        state, state->options.old_value_visitor
                   ? state->options.old_value_visitor->object_end
                   : NULL);
    if (status != LONEJSON_STATUS_OK) {
      return status;
    }
    if (state->replace_depth != 0u) {
      state->replace_depth--;
    }
    if (state->replace_depth == 0u) {
      state->replacing = 0;
      return lonejson__value_rewrite_replace_with(state);
    }
    return LONEJSON_STATUS_OK;
  }
  if (state->skipping) {
    state->skip_depth--;
    if (state->skip_depth == 0u) {
      state->skipping = 0;
    }
    return LONEJSON_STATUS_OK;
  }
  frame = lonejson__value_rewrite_top(state);
  if (frame == NULL || frame->kind != LONEJSON__VALUE_REWRITE_FRAME_OBJECT) {
    return lonejson__set_error(state->error, LONEJSON_STATUS_INTERNAL_ERROR, 0u,
                               0u, 0u, "value rewrite object frame mismatch");
  }
  status = lonejson__value_rewrite_emit_missing_chain(state, frame);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  status = lonejson_writer_end_object(&state->writer, state->error);
  if (status != LONEJSON_STATUS_OK) {
    return status;
  }
  return lonejson__value_rewrite_pop_frame(state);
}

